from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Disp_neighbors(EmssimCommand):
    def __init__(self, method='disp_neighbors', timeout=60, rpc_connection_name='localRPC'):
        super(Disp_neighbors, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Disp_neighbors, self).on_new_data(**data)
        if "neighbors" not in self._ret:
            self._ret["neighbors"] = {}

        if "exists" in data:
            exists = int(data["exists"])
            if data["rat"] not in self._ret["neighbors"]:
                self._ret["neighbors"][data["rat"]] = {}

            if data["cell"] not in self._ret["neighbors"][data["rat"]]:
                self._ret["neighbors"][data["rat"]][data["cell"]] = {}

            if exists:
                self._ret["neighbors"][data["rat"]][data["cell"]] = data["table"]
